def _config_route_gate_batch(pack_path, pack, v, history, mode, base,
                             events, queries, limit):
    # Batched hotload with a per-event routing-impact gate (config op
    # 17): [17, m, b, E, Q, L]. m is 0 (read-only preview) or 1 (atomic
    # commit); b the caller-observed base version; E a non-empty array
    # of non-decreasing-clock [e, t, p] events exactly like op 16's; Q a
    # non-empty list of distinct [s, d] pairs whose endpoints must both
    # be nodes of the h[b] topology; L a non-boolean integer in
    # 0..MAX_COST, the largest allowed single-routing cost increase.
    #
    # Inputs validate first (shapes in the command entry, t/p here, the
    # h[b] endpoint check against h[b]'s topology), then simulation walks
    # from h[b] in E order. An event whose t/p equals the previous state
    # is idempotent (row status 1, no version, no impact). Every other
    # event is a candidate version (row status 0 unless it is the first
    # failing event, row status 2): for each distinct query source the
    # route subcommand's lowest-cost paths with the deterministic
    # code-point tie break are computed before and after the event, and
    # each Q pair yields, in Q order, an impact row
    # [s, d, oldCost, newCost, oldPath, newPath, pass] with null and []
    # for an unreachable side. A pair passes when its old route was
    # unreachable, or the new route is reachable and newCost-oldCost <= L;
    # an event passes only when every pair passes. At the first failing
    # non-idempotent event simulation stops, the whole batch rejects
    # (batch status 2, old/new both the pre-call v, applied false, config
    # the pre-call pack), and nothing is written in either mode.
    #
    # With every event a candidate and the whole batch gated, version
    # append, history, duplicate-resend recognition, preview/commit
    # difference, and the single atomic replace follow op 16 exactly.
    # O(BK(V^2+A) + S) time and O(S + BRV + KV) extra space: B events,
    # K distinct query sources (K <= R queries), R queries, V nodes, A
    # links, and S the total input/output size.
    if base > v:
        fail(5)
    base_topo = history[base][1]
    base_nodes = set(base_topo["nodes"])
    for s, d in queries:
        if s not in base_nodes or d not in base_nodes:
            fail(5)
    for item in events:
        _validate_topology(item[1], metrics=True)
        if not _is_policy(item[2]):
            fail(5)

    # Routes on the running topology, computed once per distinct Q source
    # and reused until an event actually changes the topology. The h[b]
    # routes are shared by every event's "before" side.
    cur_version = base
    cur_t = history[base][1]
    cur_p = history[base][2]
