    # Batched hotload with a per-event routing-impact gate (config op
    # 17): [17, m, b, E, Q, L]. m is 0 (read-only preview) or 1 (atomic
    # commit); b the caller-observed base version; E a non-empty array
    # of non-decreasing-clock [e, t, p] events exactly like op 16's; Q a
    # non-empty list of distinct [s, d] pairs whose endpoints must both
    # be nodes of the h[b] topology; L a non-boolean integer in
    # 0..MAX_COST, the largest allowed single-routing cost increase.
    #
    # Inputs validate first (shapes in the command entry, t/p here, the
    # h[b] endpoint check against h[b]'s topology), then simulation walks
    # from h[b] in E order. An event whose t/p equals the previous state
    # is idempotent (row status 1, no version, no impact). Every other
    # event is a candidate version (row status 0 unless it is the first
    # failing event, row status 2): for each distinct query source the
    # route subcommand's lowest-cost paths with the deterministic
    # code-point tie break are computed before and after the event, and
    # each Q pair yields, in Q order, an impact row
    # [s, d, oldCost, newCost, oldPath, newPath, pass] with null and []
    # for an unreachable side. A pair passes when its old route was
    # unreachable, or the new route is reachable and newCost-oldCost <= L;
    # an event passes only when every pair passes. At the first failing
    # non-idempotent event simulation stops, the whole batch rejects
    # (batch status 2, old/new both the pre-call v, applied false, config
    # the pre-call pack), and nothing is written in either mode.
    #
    # With every event a candidate and the whole batch gated, version
    # append, history, duplicate-resend recognition, preview/commit
    # difference, and the single atomic replace follow op 16 exactly.
    # O(BK(V^2+A) + S) time and O(S + BRV + KV) extra space: B events,
    # K distinct query sources (K <= R queries), R queries, V nodes, A
    # links, and S the total input/output size.
    if base > v:
        fail(5)
    base_topo = history[base][1]
    base_nodes = set(base_topo["nodes"])
    for s, d in queries:
        if s not in base_nodes or d not in base_nodes:
            fail(5)
    for item in events:
        _validate_topology(item[1], metrics=True)
        if not _is_policy(item[2]):
            fail(5)

    # Routes on the running topology, computed once per distinct Q source
    # and reused until an event actually changes the topology. The h[b]
    # routes are shared by every event's "before" side.
    cur_version = base
    cur_t = history[base][1]
    cur_p = history[base][2]
    cur_nodes = cur_t["nodes"]
    cur_links = cur_t["links"]
    cur_cost = {}
    cur_path = {}
    for s, _d in queries:
        if s not in cur_cost:
            cur_cost[s], cur_path[s] = shortest_paths(cur_nodes, cur_links,
                                                      s)

    def route_lookup(cost_map, path_map, s, d):
        c = cost_map[s][d]
        if c is None:
            return None, []
        return c, path_map[s][d]

    rows = []
    suffix = []
    last_e = None
    for event in events:
        e, new_t, new_p = event
        if last_e is not None and e < last_e:
            fail(5)
        last_e = e
        if new_t == cur_t and new_p == cur_p:
            rows.append([e, 1, cur_version, cur_version, []])
            continue
        if cur_version >= MAX_COST:
            fail(5)
        # Before/after routes for the distinct sources of Q only.
        new_nodes = new_t["nodes"]
        new_links = new_t["links"]
        new_cost = {}
        new_path = {}
        sources = []
        for s, _d in queries:
            if s not in new_cost and s in base_nodes:
                sources.append(s)
        for s in sources:
            if s not in set(new_nodes):
                # A query source removed by the candidate topology has no
                # routes there: represent every destination as unreachable.
                new_cost[s] = {d: None for _, d in queries
                               if False}
                new_path[s] = {}
            else:
                new_cost[s], new_path[s] = shortest_paths(new_nodes,
                                                          new_links, s)
        impact = []
        passed = True
        for s, d in queries:
            old_cost, old_path = route_lookup(cur_cost, cur_path, s, d)
            if s not in set(new_nodes) or d not in set(new_nodes):
                n_cost, n_path = None, []
            else:
                n_cost, n_path = route_lookup(new_cost, new_path, s, d)
            if old_cost is None:
                pair_pass = True
            else:
                pair_pass = (n_cost is not None
                             and n_cost - old_cost <= limit)
            if not pair_pass:
                passed = False
            impact.append([s, d, old_cost, n_cost, old_path, n_path,
                           pair_pass])
        next_version = cur_version + 1
        if not passed:
            rows.append([e, 2, cur_version, cur_version, impact])
            return {"op": 17, "mode": mode, "status": 2, "old": v,
                    "new": v, "applied": False, "events": rows,
                    "config": pack}
        rows.append([e, 0, cur_version, next_version, impact])
        suffix.append([next_version, res_t_placeholder(new_t), new_p])
        cur_version = next_version
        cur_t, cur_p = new_t, new_p
        cur_nodes, cur_links = new_nodes, new_links
        cur_cost, cur_path = new_cost, new_path
    change_count = len(suffix)

    if base != v:
        # The only tolerated stale base is an exact resend: PACK must
        # already end exactly at the simulated suffix with every entry
        # equal; anything else is a version/suffix conflict.
        if change_count == 0 or v != base + change_count:
            fail(5)
        for offset, entry in enumerate(suffix, start=1):
            if history[base + offset] != entry:
                fail(5)
        return {"op": 17, "mode": mode, "status": 1, "old": base,
                "new": v, "applied": False, "events": rows,
                "config": pack}

    if change_count == 0:
        # All events idempotent at the current version: nothing to
        # append, so a commit writes nothing either.
        return {"op": 17, "mode": mode, "status": 0, "old": base,
                "new": base, "applied": False, "events": rows,
                "config": pack}
    new_pack = {"v": v + change_count, "t": cur_t, "p": cur_p,
                "h": history + suffix}
    if mode == 1:
        _write_state_atomic(pack_path, new_pack)
        applied = True
    else:
        applied = False
    return {"op": 17, "mode": mode, "status": 0, "old": base,
            "new": v + change_count, "applied": applied, "events": rows,
            "config": new_pack}

